211	
212	      <button
213	        type="button"
214	        className="delete-button"
215	        onClick={handleDelete}
216	        aria-label={todo.text ? `Delete todo: ${todo.text}` : 'Delete todo'}
217	        disabled={isEditing}
218	      >
219	        Delete
220	      </button>
221	    </li>
222	  );
223	}
